   130→    func buildRecordingWaveform() async -> Result<[Float], VoiceMessageRecorderError> {
   131→        guard let url = audioRecorder.audioFileURL else {
   132→            return .failure(.missingRecordingFile)
   133→        }
   134→        // build the waveform
   135→        var waveformData: [Float] = []
   136→        let analyzer = WaveformAnalyzer()
   137→        do {
   138→            let samples = try await analyzer.samples(fromAudioAt: url, count: 100)
   139→            // linearly normalized to [0, 1] (1 -> -50 dB)
   140→            waveformData = samples.map { max(0, 1 - $0) }
   141→        } catch {
   142→            MXLog.error("Waveform analysis failed. \(error)")
   143→            return .failure(.waveformAnalysisError)
