   148→    func sendVoiceMessage(timelineController: TimelineControllerProtocol,
   149→                          audioConverter: AudioConverterProtocol) async -> Result<Void, VoiceMessageRecorderError> {
   150→        guard let url = audioRecorder.audioFileURL else {
   151→            return .failure(VoiceMessageRecorderError.missingRecordingFile)
   152→        }
   153→        
   154→        // convert the file
   155→        let sourceFilename = url.deletingPathExtension().lastPathComponent
   156→        let oggFile = URL.temporaryDirectory.appendingPathComponent(sourceFilename).appendingPathExtension("ogg")
   157→        defer {
   158→            // delete the temporary file
   159→            try? FileManager.default.removeItem(at: oggFile)
   160→        }
   161→
   162→        do {
   163→            try audioConverter.convertToOpusOgg(sourceURL: url, destinationURL: oggFile)
   164→        } catch {
   165→            return .failure(.failedSendingVoiceMessage)
   166→        }
   167→
   168→        // send it
   169→        let size: UInt64
   170→        do {
   171→            size = try UInt64(FileManager.default.sizeForItem(at: oggFile))
   172→        } catch {
   173→            MXLog.error("Failed to get the recording file size. \(error)")
   174→            return .failure(.failedSendingVoiceMessage)
   175→        }
   176→        let audioInfo = AudioInfo(duration: recordingDuration, size: size, mimetype: "audio/ogg")
   177→        guard case .success(let waveform) = await buildRecordingWaveform() else {
   178→            return .failure(.failedSendingVoiceMessage)
   179→        }
   180→        
   181→        let result = await timelineController.sendVoiceMessage(url: oggFile,
   182→                                                               audioInfo: audioInfo,
   183→                                                               waveform: waveform) { _ in }
   184→        
   185→        if case .failure(let error) = result {
   186→            MXLog.error("Failed to send the voice message. \(error)")
   187→            return .failure(.failedSendingVoiceMessage)
   188→        }
   189→        
   190→        return .success(())
   191→    }
