   208→    private func handleAudioRecorderAction(_ action: AudioRecorderAction) {
   209→        switch action {
   210→        case .didStartRecording:
   211→            MXLog.info("audio recorder did start recording")
   212→            actionsSubject.send(.didStartRecording(audioRecorder: audioRecorder))
   213→        case .didStopRecording, .didFailWithError(error: .interrupted):
   214→            MXLog.info("audio recorder did stop recording")
   215→            if !recordingCancelled {
   216→                Task {
   217→                    guard case .success = await finalizeRecording() else {
   218→                        actionsSubject.send(.didFailWithError(error: VoiceMessageRecorderError.previewNotAvailable))
   219→                        return
   220→                    }
   221→                    guard let recordingURL = audioRecorder.audioFileURL, let previewAudioPlayerState else {
   222→                        actionsSubject.send(.didFailWithError(error: VoiceMessageRecorderError.previewNotAvailable))
   223→                        return
   224→                    }
   225→                    await mediaPlayerProvider.register(audioPlayerState: previewAudioPlayerState)
   226→                    actionsSubject.send(.didStopRecording(previewState: previewAudioPlayerState, url: recordingURL))
   227→                }
   228→            }
   229→        case .didFailWithError(let error):
   230→            MXLog.info("audio recorder did failed with error: \(error)")
   231→            actionsSubject.send(.didFailWithError(error: .audioRecorderError(error)))
   232→        }
   233→    }
