    15→private enum InternalAudioRecorderState: Equatable {
    16→    case recording
    17→    case suspended
    18→    case stopped
    19→    case error(AudioRecorderError)
    20→}
    21→
    22→class AudioRecorder: AudioRecorderProtocol {
    23→    private let audioSession: AudioSessionProtocol
    24→    private var audioEngine: AVAudioEngine?
    25→    private var mixer: AVAudioMixerNode?
    26→    private var audioFile: AVAudioFile?
    27→    private var audioConverter: AVAudioConverter?
    28→    private var internalState = InternalAudioRecorderState.stopped
    29→    
    30→    private var cancellables = Set<AnyCancellable>()
    31→    private let actionsSubject: PassthroughSubject<AudioRecorderAction, Never> = .init()
    32→    var actions: AnyPublisher<AudioRecorderAction, Never> {
    33→        actionsSubject.eraseToAnyPublisher()
    34→    }
    35→    
    36→    private var recordingFormat: AVAudioFormat!
    37→    private let maximumRecordingTime: TimeInterval = 1800 // 30 minutes
    38→    private let silenceThreshold: Float = -50.0
    39→    private var meterLevel: Float = 0
    40→
    41→    private(set) var audioFileURL: URL?
    42→    var currentTime: TimeInterval = .zero
    43→    var isRecording: Bool {
    44→        audioEngine?.isRunning ?? false
    45→    }
    46→    
    47→    private let dispatchQueue = DispatchQueue(label: "io.element.elementx.audio_recorder", qos: .userInitiated)
    48→    private var stopped = false
    49→    
    50→    init(audioSession: AudioSessionProtocol = AVAudioSession.sharedInstance()) {
    51→        self.audioSession = audioSession
    52→    }
    53→    
    54→    deinit {
    55→        if isRecording {
    56→            // Cleanup
    57→            cleanupAudioEngine()
    58→            deleteRecordingFile()
    59→        }
    60→    }
    61→    
    62→    func record(audioFileURL: URL) async {
    63→        stopped = false
    64→        guard await requestRecordPermission() else {
    65→            setInternalState(.error(.recordPermissionNotGranted))
    66→            return
    67→        }
    68→        let result = await startRecording(audioFileURL: audioFileURL)
    69→        switch result {
    70→        case .success:
    71→            setInternalState(.recording)
    72→        case .failure(let error):
    73→            setInternalState(.error(error))
    74→        }
    75→    }
