   102→    // MARK: - Private
   103→    
   104→    private func requestRecordPermission() async -> Bool {
   105→        await withCheckedContinuation { continuation in
   106→            audioSession.requestRecordPermission { granted in
   107→                continuation.resume(returning: granted)
   108→            }
   109→        }
