   111→    
   112→    private func setupAudioSession() throws {
   113→        MXLog.info("setup audio session")
   114→        
   115→        try audioSession.setAllowHapticsAndSystemSoundsDuringRecording(true)
   116→        try audioSession.setCategory(.playAndRecord, mode: .default, options: [.allowBluetooth])
   117→        try audioSession.setActive(true)
   118→        addObservers()
   119→    }
   120→    
   121→    private func releaseAudioSession() {
   122→        MXLog.info("releasing audio session")
   123→        try? audioSession.setActive(false, options: .notifyOthersOnDeactivation)
   124→        removeObservers()
   125→    }
   126→    
   127→    private func startRecording(audioFileURL: URL) async -> Result<Void, AudioRecorderError> {
   128→        await withCheckedContinuation { continuation in
   129→            startRecording(audioFileURL: audioFileURL) { result in
   130→                continuation.resume(returning: result)
   131→            }
   132→        }
   133→    }
   134→    
   135→    private func createAudioFile(at recordingURL: URL) throws -> AVAudioFile {
   136→        let settings = [AVFormatIDKey: Int(kAudioFormatMPEG4AAC),
   137→                        AVSampleRateKey: Int(recordingFormat.sampleRate),
   138→                        AVEncoderBitRateKey: 128_000,
   139→                        AVNumberOfChannelsKey: 1,
   140→                        AVEncoderAudioQualityKey: AVAudioQuality.high.rawValue]
   141→        MXLog.info("creating audio file with format: \(settings)")
   142→        try? FileManager.default.removeItem(at: recordingURL)
   143→        return try AVAudioFile(forWriting: recordingURL, settings: settings)
   144→    }
   145→    
   146→    private func startRecording(audioFileURL: URL, completion: @escaping (Result<Void, AudioRecorderError>) -> Void) {
   147→        dispatchQueue.async { [weak self] in
   148→            guard let self, !self.stopped else {
   149→                completion(.failure(.recordingCancelled))
   150→                return
   151→            }
   152→            
   153→            do {
   154→                try setupAudioSession()
   155→            } catch {
   156→                MXLog.error("failed to setup audio session. \(error)")
   157→                completion(.failure(.audioSessionFailure))
   158→                return
   159→            }
   160→            
   161→            // Initialize a new audio engine
   162→            let audioEngine = AVAudioEngine()
   163→            self.audioEngine = audioEngine
   164→
   165→            let inputNode = audioEngine.inputNode
   166→            let inputFormat = inputNode.outputFormat(forBus: 0)
   167→            let hardwareSampleRate = audioEngine.inputNode.outputFormat(forBus: 0).sampleRate
   168→            
   169→            // Define a recording audio format. Force the sample rate to 48000 to ensure OGGEncoder won't crash
   170→            guard let recordingFormat = AVAudioFormat(standardFormatWithSampleRate: 48000, channels: 1) else {
   171→                completion(.failure(.unsupportedAudioFormat))
   172→                return
   173→            }
   174→            self.recordingFormat = recordingFormat
   175→            
   176→            // Make sure we have 1 channel at the end by using a mixer.
   177→            // The sample rate must match the hardware sample rate.
   178→            let mixerFormat = AVAudioFormat(standardFormatWithSampleRate: hardwareSampleRate, channels: 1)
   179→            let mixer = AVAudioMixerNode()
   180→            self.mixer = mixer
   181→            audioEngine.attach(mixer)
   182→            audioEngine.connect(audioEngine.inputNode, to: mixer, format: inputFormat)
   183→            
   184→            // Reset the recording duration
   185→            currentTime = 0
   186→            // Create an audio file
   187→            let audioFile: AVAudioFile
   188→            do {
   189→                audioFile = try createAudioFile(at: audioFileURL)
   190→                self.audioFile = audioFile
   191→                self.audioFileURL = audioFile.url
   192→            } catch {
   193→                MXLog.error("failed to create an audio file. \(error)")
   194→                completion(.failure(.audioFileCreationFailure))
   195→                releaseAudioSession()
   196→                return
   197→            }
   198→            
   199→            // Set up an audio converter if the hardware sample rate doesn't match the recording format.
   200→            // Note: Not all Apple devices have the same default sample rate.
   201→            if recordingFormat.sampleRate != hardwareSampleRate {
   202→                MXLog.info("Sample rate conversion is needed \(hardwareSampleRate) -> \(recordingFormat.sampleRate)")
   203→                audioConverter = AVAudioConverter(from: inputFormat, to: recordingFormat)
   204→            } else {
   205→                audioConverter = nil
   206→            }
   207→
   208→            // Install tap to process audio buffers coming from the mixer
   209→            mixer.installTap(onBus: 0, bufferSize: 1024, format: mixerFormat) { [weak self] buffer, _ in
   210→                self?.processAudioBuffer(buffer)
   211→            }
   212→
   213→            do {
   214→                try audioEngine.start()
   215→                completion(.success(()))
   216→            } catch {
   217→                MXLog.error("audio recording failed to start. \(error)")
   218→                completion(.failure(.audioEngineFailure))
   219→            }
   220→        }
   221→    }
   222→    
   223→    private func stopRecording(completion: @escaping () -> Void) {
   224→        dispatchQueue.async { [weak self] in
   225→            defer {
   226→                completion()
   227→            }
   228→            guard let self else { return }
   229→            stopped = true
   230→            cleanupAudioEngine()
