   272→    // MARK: Audio Processing
   273→    
   274→    private func processAudioBuffer(_ buffer: AVAudioPCMBuffer) {
   275→        guard let audioFile else {
   276→            return
   277→        }
   278→        
   279→        var inputBuffer = buffer
   280→        if let audioConverter {
   281→            // Create an AVAudioPCMBuffer instance for the converted buffer
   282→            let conversionRatio = buffer.format.sampleRate / recordingFormat.sampleRate
   283→            let frameCapacity = UInt32(Double(buffer.frameLength) / conversionRatio)
   284→            guard let convertedBuffer = AVAudioPCMBuffer(pcmFormat: recordingFormat, frameCapacity: frameCapacity) else {
   285→                MXLog.error("failed to initialize an output buffer")
   286→                return
   287→            }
   288→            
   289→            // Convert the buffer
   290→            let inputBlock: AVAudioConverterInputBlock = { _, outStatus in
   291→                outStatus.pointee = AVAudioConverterInputStatus.haveData
   292→                return buffer
   293→            }
   294→            
   295→            var conversionError: NSError?
   296→            audioConverter.convert(to: convertedBuffer, error: &conversionError, withInputFrom: inputBlock)
   297→            if let conversionError {
   298→                MXLog.info("audio conversion failed: \(conversionError)")
   299→                return
   300→            }
   301→            inputBuffer = convertedBuffer
   302→        }
   303→        
   304→        // Write the buffer into the audio file
   305→        do {
   306→            try audioFile.write(from: inputBuffer)
   307→
   308→            // Compute the sample value for the waveform
   309→            updateMeterLevel(inputBuffer)
   310→            
   311→            // Update the recording duration only if we succeed to write the buffer
   312→            currentTime += Double(inputBuffer.frameLength) / inputBuffer.format.sampleRate
   313→            
   314→            // Limit the recording time
   315→            if currentTime >= maximumRecordingTime {
   316→                MXLog.info("Maximum recording time reach (\(maximumRecordingTime))")
   317→                Task { await stopRecording() }
   318→            }
   319→        } catch {
   320→            MXLog.error("failed to write sample. \(error)")
   321→        }
   322→    }
   323→    
   324→    // MARK: Observers
   325→    
   326→    private func addObservers() {
   327→        removeObservers()
   328→        // Stop recording uppon UIApplication.didEnterBackgroundNotification notification
   329→        NotificationCenter.default.publisher(for: UIApplication.willResignActiveNotification)
   330→            .sink { [weak self] _ in
   331→                guard let self else { return }
   332→                MXLog.warning("Application will resign active while recording.")
   333→                Task { await self.stopRecording() }
   334→            }
   335→            .store(in: &cancellables)
   336→        
   337→        NotificationCenter.default.publisher(for: Notification.Name.AVAudioEngineConfigurationChange)
