   368→            MXLog.info("Interruption ended: \(notification)")
   369→
   370→            guard let optionsValue = userInfo[AVAudioSessionInterruptionOptionKey] as? UInt else { return }
   371→            let options = AVAudioSession.InterruptionOptions(rawValue: optionsValue)
